mapper.update:
UPDATE ${admin.sessions}
SET token_hash = #{tokenHash}, state = #{state}, absolute_expires_at = #{absoluteExpiresAt},
    mfa_verified_at = COALESCE(#{mfaVerifiedAt}, mfa_verified_at), mfa_failed_attempts = 0,
    last_activity_at = #{now}
WHERE id = #{sessionId}

UPDATE ${admin.sessions} SET revoked_at = #{now}, revoke_reason = #{reason}
WHERE ${admin.userId} = #{userId} AND revoked_at IS NULL
AND id <> #{exceptSessionId}

mapper.select:
SELECT 
FROM ${admin.sessions}
WHERE ${admin.userId} = #{userId} AND revoked_at IS NULL AND absolute_expires_at > #{now}
ORDER BY last_activity_at DESC
